// Isolated UCI worker for optional, local free practice. No network requests.
(()=>{'use strict';let worker=null,url=null,active=null,ready=null,readyResolve=null,readyReject=null,initTimer=null;const error=()=>new Error('Подготовка соперника отменена');
function cancel(){clearTimeout(initTimer);if(active){clearTimeout(active.timer);active.reject(error());active=null}if(readyReject)readyReject(error());readyResolve=readyReject=null;ready=null;if(worker)worker.terminate();worker=null;if(url)URL.revokeObjectURL(url);url=null}
function init(){if(ready)return ready;ready=new Promise((resolve,reject)=>{readyResolve=resolve;readyReject=reject;try{url=URL.createObjectURL(new Blob([window.ENDGAME_ENGINE_SOURCE],{type:'application/javascript'}));worker=new Worker(url);worker.onmessage=e=>{const line=String(e.data);if(line==='uciok'){worker.postMessage('setoption name Hash value 16');worker.postMessage('isready')}if(line==='readyok'&&readyResolve){clearTimeout(initTimer);const done=readyResolve;readyResolve=readyReject=null;done()}const m=line.match(/^info depth (\d+).*?score (cp|mate) (-?\d+).*? pv (.+)/);if(m&&active)active.info={depth:+m[1],type:m[2],score:+m[3],pv:m[4].split(' ')};if(line.startsWith('bestmove ')&&active){const pending=active;active=null;clearTimeout(pending.timer);pending.resolve({...pending.info,move:line.split(' ')[1]})}};worker.onerror=()=>cancel();worker.postMessage('uci');initTimer=setTimeout(()=>cancel(),12000)}catch(e){readyResolve=readyReject=null;ready=null;reject(e)}});return ready}
async function analyze(fen){await init();if(active)throw Error('Соперник ещё обдумывает ход');return new Promise((resolve,reject)=>{active={resolve,reject,info:null,timer:setTimeout(()=>cancel(),8000)};worker.postMessage('position fen '+fen);worker.postMessage('go depth 20 movetime 650')})}
window.EndgameEngine={analyze,cancel};
})();
